import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { AgentOutcome, AgentRun, AskContext, CommandRunner, Harness, HarnessReply, TokenUsage } from "@amykit/core";
import { costOf, specFor } from "@amykit/model-specs";

export interface HermesHarnessConfig {
  model?: string;
  timeoutMs?: number;
  /**
   * The profile the run is in. Without one, `-z` runs in the operator's own
   * Hermes: their memory read into the run, and whatever it learns written
   * back, with approvals bypassed.
   */
  profile?: string;
}

/** The report `--usage-file` writes, which it writes even on a failed run. */
export interface HermesUsage {
  estimated_cost_usd?: number;
  cost_status?: string;
  cost_source?: string;
  input_tokens?: number;
  output_tokens?: number;
  cache_read_tokens?: number;
  cache_write_tokens?: number;
  model?: string;
  provider?: string;
  completed?: boolean;
  failed?: boolean;
  failure_reason?: string;
  failure_resets_at?: string;
}

/**
 * Hermes, over its one-shot mode.
 *
 * `-z` prints only the final response, and `--usage-file` writes the account
 * beside it. The account is written **even when the run fails**, which is the
 * nicest property of the three harnesses: a failed run still says what it
 * spent, so nothing is silently free.
 */
export class HermesHarness implements Harness {
  readonly name = "hermes";

  constructor(
    private readonly runner: CommandRunner,
    private readonly config: HermesHarnessConfig = {},
    private readonly tmpDir: string = os.tmpdir(),
  ) {}

  async ask(prompt: string, cwd: string, context: AskContext = {}): Promise<HarnessReply> {
    // `-z` has no mode that keeps the agent's tools off the checkout, so a run
    // that must change nothing is refused before it starts, and a relay hands
    // it to a harness that can enforce it.
    if (context.readOnly) {
      const output = "hermes -z cannot run without write access to the checkout, so it does not take a read-only step";
      return {
        text: "",
        run: { outcome: "failed", harness: this.name, model: this.config.model ?? "", durationMs: 0, costSource: "unknown", output },
      };
    }
    const report = path.join(this.tmpDir, `amy-hermes-${process.pid}-${Date.now()}.json`);
    const args = this.config.profile ? ["-p", this.config.profile] : [];
    args.push("-z", prompt, "--usage-file", report);
    if (this.config.model) {
      args.push("-m", this.config.model);
    }

    const started = Date.now();
    const result = await this.runner.run("hermes", args, {
      cwd,
      timeoutMs: this.config.timeoutMs,
    });

    const usage = readUsage(report);
    fs.rmSync(report, { force: true });

    const tokens = tokensOf(usage);
    const model = usage?.model ?? this.config.model ?? "";

    return {
      text: result.stdout,
      run: {
        outcome: classify(usage, result.ok),
        harness: this.name,
        model,
        tokens,
        ...cost(usage, tokens, model),
        durationMs: Date.now() - started,
        ...(retryAfterMs(usage) === undefined ? {} : { retryAfterMs: retryAfterMs(usage) }),
        output: [result.stdout, result.stderr].filter(Boolean).join("\n").trim(),
      } satisfies AgentRun,
    };
  }
}

export function readUsage(file: string): HermesUsage | undefined {
  if (!fs.existsSync(file)) return undefined;

  try {
    return JSON.parse(fs.readFileSync(file, "utf-8")) as HermesUsage;
  } catch {
    return undefined;
  }
}

/**
 * The token counts.
 *
 * `input_tokens` here **excludes** what was served from cache: the report's
 * own `total_tokens` is the sum of input, output and cache reads. That is the
 * opposite of the convention codex uses for a field of the same name, so
 * neither can borrow the other's mapping.
 */
export function tokensOf(usage: HermesUsage | undefined): TokenUsage | undefined {
  if (!usage) return undefined;

  return {
    input: usage.input_tokens ?? 0,
    output: usage.output_tokens ?? 0,
    cacheRead: usage.cache_read_tokens ?? 0,
    cacheWrite: usage.cache_write_tokens ?? 0,
  };
}

/**
 * What it cost, and how that is known.
 *
 * `cost_status: "included"` means a subscription covered the run, so zero is
 * the right answer rather than a missing one. Anything else Hermes puts in
 * `estimated_cost_usd` is, by its own word, an estimate from a price table,
 * so it is recorded as `computed` rather than `reported`: presenting somebody
 * else's estimate as a measurement is exactly what `costSource` exists to
 * stop.
 */
export function cost(
  usage: HermesUsage | undefined,
  tokens: TokenUsage | undefined,
  model: string,
): { costUsd?: number; costSource: AgentRun["costSource"] } {
  if (usage?.cost_status === "included") {
    return { costUsd: 0, costSource: "included" };
  }

  if (typeof usage?.estimated_cost_usd === "number" && usage.estimated_cost_usd > 0) {
    return { costUsd: usage.estimated_cost_usd, costSource: "computed" };
  }

  if (tokens) {
    const spec = specFor(model);
    if (spec) return { costUsd: costOf(spec, tokens), costSource: "computed" };
  }

  return { costSource: "unknown" };
}

/**
 * Which outcome this was.
 *
 * The report says plainly whether the run completed or failed, which beats
 * an exit code. Hermes publishes no quota status, so a rate limit reads as
 * `failed` rather than `rate-limited`.
 */
export function classify(usage: HermesUsage | undefined, exitOk: boolean): AgentOutcome {
  if (!usage) return exitOk ? "completed" : "abandoned";
  if (usage.failure_reason === "rate_limit") return "rate-limited";
  if (usage.failed === true) return "failed";
  if (usage.completed === true) return "completed";
  return exitOk ? "completed" : "failed";
}

/** Provider reset timestamps are optional; absent keeps the workflow fallback. */
export function retryAfterMs(usage: HermesUsage | undefined, now = Date.now()): number | undefined {
  if (usage?.failure_reason !== "rate_limit" || !usage.failure_resets_at) return undefined;
  const at = Date.parse(usage.failure_resets_at);
  return Number.isNaN(at) ? undefined : Math.max(0, at - now);
}

import { ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  model: {
    type: "string",
    description: "passed to the CLI as --model. Empty leaves the choice to hermes",
    default: "",
  },
  models: {
    type: "string[]",
    description:
      "the model tiers to offer the relay, cheapest first. One agent is contributed per tier, named `hermes:<model>`. Empty means a single agent named `hermes`",
    default: [],
  },
  profile: {
    type: "string",
    description:
      "the Hermes profile amy's runs use, so they read and write nothing of the operator's own Hermes. `amy init` creates it from the active profile when it is missing. A blank one is refused at boot",
    default: "amy",
  },
  timeoutMs: {
    type: "number",
    description: "how long one agent call may run before it is given up on",
    default: 30 * 60 * 1000,
  },
} satisfies ConfigSchema;

export { HermesHarness, classify, cost, readUsage, retryAfterMs, tokensOf } from "./HermesHarness.js";
export type { HermesHarnessConfig, HermesUsage } from "./HermesHarness.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";
export { PROFILE_SETTINGS, checkProfile, prepareProfile } from "./profile.js";

import { NodeCommandRunner, definePlugin } from "@amykit/core";
import { contributeTiers } from "@amykit/agent-kit";
import { HermesHarness } from "./HermesHarness.js";
import { configSchema } from "./config.js";
import { checkProfile, prepareProfile } from "./profile.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-hermes-agent",
  configSchema,
  setup: [
    {
      name: "hermes profile",
      run: ({ runner, settings }) => prepareProfile(runner, settings.profile),
    },
  ],
  checks: [
    {
      name: "hermes profile",
      run: ({ settings }) => checkProfile(new NodeCommandRunner(), settings.profile),
    },
  ],
  register(registry, ctx) {
    // A blank profile would run `-z` in the operator's own Hermes, which is
    // the one thing the setting exists to prevent.
    if (!ctx.config.profile.trim()) {
      throw new Error("`profile` is blank, which would run Hermes in the operator's own profile: name the profile amy's runs use, such as amy");
    }
    const tiers = ctx.config.models;

    contributeTiers(registry, {
      harness: "hermes",
      // Hermes writes its own account: `cost_status: "included"` for a run a
      // subscription or a local model covered, where zero is the right
      // answer rather than a missing one, and `estimated_cost_usd` for the
      // providers it prices itself. Neither needs a row here, and a local
      // model would never have one.
      pricesItsOwnRuns: true,
      models: tiers.length > 0 ? tiers : [(ctx.config.model) || ""],
      make: (model) =>
        new HermesHarness(ctx.runner, {
          model: model || undefined,
          timeoutMs: ctx.config.timeoutMs,
          profile: ctx.config.profile,
        }),
    });
  },
});

import { Check, CommandRunner } from "@amykit/core";

/**
 * What the profile amy runs in has switched off, and why each one.
 *
 * `-z` bypasses approvals, so in the operator's own Hermes a ticket run read
 * their memory and wrote what it learned back: memories, and skills patched
 * or created, with nobody asked. In amy's profile the run remembers nothing,
 * a skill it wants to write waits for a person, and the curator does not
 * rework skills between runs.
 */
export const PROFILE_SETTINGS: readonly { key: string; value: string; says: string }[] = [
  { key: "memory.memory_enabled", value: "false", says: "remembers between runs" },
  { key: "memory.user_profile_enabled", value: "false", says: "keeps a profile of the user" },
  { key: "skills.write_approval", value: "true", says: "writes skills unasked" },
  { key: "curator.enabled", value: "false", says: "curates skills between runs" },
];

const DESCRIPTION = "amy's runs: one-shot ticket work that keeps no memory and writes no skill unasked";

/**
 * Makes the profile amy runs in, once.
 *
 * Cloned from the active profile, which carries the model, the provider keys
 * and the skills; Hermes reads the login through its credential pool, so the
 * clone needs no second sign-in. A profile that exists is left alone: what is
 * in it is whoever edited it, and the doctor is what says when it drifted.
 */
export async function prepareProfile(runner: CommandRunner, profile: string): Promise<Check> {
  const label = `hermes profile ${profile}`;
  if (await exists(runner, profile)) return { label, ok: true, detail: "kept: it already exists" };

  const created = await runner.run("hermes", ["profile", "create", profile, "--clone", "--no-alias", "--description", DESCRIPTION]);
  if (!created.ok) return { label, ok: false, detail: failure("could not create it", created) };

  for (const setting of PROFILE_SETTINGS) {
    const set = await runner.run("hermes", ["-p", profile, "config", "set", setting.key, setting.value]);
    if (!set.ok) return { label, ok: false, detail: failure(`created it, but could not set ${setting.key}`, set) };
  }

  return { label, ok: true, detail: "created from the active profile, with memory, unasked skill writes and the curator off" };
}

/**
 * Whether the profile exists and still has off what amy turned off.
 *
 * Red names the command that puts each one back, rather than putting it back:
 * somebody turned it on, and the doctor is not the place to overrule them.
 */
export async function checkProfile(runner: CommandRunner, profile: string): Promise<Check> {
  const label = `hermes profile ${profile}`;
  if (!(await exists(runner, profile))) {
    // Only `amy init`: a bare clone copies the active profile's settings, so
    // it would come back remembering and curating, and the doctor still red.
    return { label, ok: false, detail: "missing: run `amy init`, which creates it with memory, unasked skill writes and the curator off" };
  }

  const drifted: string[] = [];
  for (const setting of PROFILE_SETTINGS) {
    const got = await runner.run("hermes", ["-p", profile, "config", "get", setting.key]);
    if (got.stdout.trim().toLowerCase() !== setting.value) {
      drifted.push(`${setting.says} (\`hermes -p ${profile} config set ${setting.key} ${setting.value}\`)`);
    }
  }

  return drifted.length === 0
    ? { label, ok: true }
    : { label, ok: false, detail: `the profile ${drifted.join("; ")}` };
}

async function exists(runner: CommandRunner, profile: string): Promise<boolean> {
  return (await runner.run("hermes", ["profile", "show", profile])).ok;
}

function failure(what: string, result: { stdout: string; stderr: string; exitCode: number | null }): string {
  const said = (result.stderr || result.stdout).trim();
  return said ? `${what}: ${said}` : `${what} (exit ${result.exitCode})`;
}
